// sverity-args: --top top --sdc @FIXTURES@/_common/async.sdc
// A reset generated by logic (not a primary input) has an unresolved source.
// expect: RDC-001 WARNING
module top(input logic clka, rst_a, rst_b, d, output logic q);
  logic rst_n;
  assign rst_n = rst_a & rst_b;
  always_ff @(posedge clka or negedge rst_n) if (!rst_n) q <= 1'b0; else q <= d;
endmodule
